{"candidate_predicates": [
  {
    "name": "ATTRIBUTES_FAILURE_TO_OWN_TEST_HARNESS",
    "definition": "The reasoning concludes that an observed failure originates in the agent's own verification code or its test-data construction rather than in the artifact or service under test, so the appropriate response is to correct the check instead of the target system.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text diagnosing the cause of the failure."
      },
      {
        "name": "failure",
        "type": "observation",
        "description": "The observation reporting the unsuccessful result being diagnosed."
      }
    ],
    "assertion_conditions": [
      "The reasoning explicitly identifies the cause of the failure as a defect in the agent's own test code, script, or input handling.",
      "The reasoning distinguishes that defect from a fault in the system being tested."
    ],
    "exclusion_conditions": [
      "The reasoning attributes the failure to the target system's implementation.",
      "The reasoning merely reports the failure or restates the error without assigning a cause.",
      "The reasoning proposes a repair to the target system rather than to the test procedure."
    ]
  },
  {
    "name": "REEXECUTES_CHECK_WITH_CORRECTED_TEST_INPUT",
    "definition": "After diagnosing a defect in the construction of a test input, the action repeats the same check with that input construction corrected, leaving the checked behavior and the target system unchanged.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The repeated invocation that exercises the same behavior with corrected input."
      },
      {
        "name": "diagnosis",
        "type": "reasoning",
        "description": "The reasoning that names the specific defect in the earlier test input and states the correction."
      }
    ],
    "assertion_conditions": [
      "The diagnosis identifies a concrete defect in how the previous test request or input was formed (for example, an encoding or type mismatch).",
      "The action exercises the same target behavior as the earlier attempt, with the identified input defect corrected.",
      "The action does not modify the target system, only the test input."
    ],
    "exclusion_conditions": [
      "The action changes the behavior under test, the endpoint, or the scope of the check.",
      "The action repairs or reconfigures the target system.",
      "No prior diagnosis of a test-input defect is present."
    ]
  },
  {
    "name": "ADAPTS_VERIFICATION_TO_ALTERNATIVE_TOOLING",
    "definition": "An observation reports that the tool or command needed for a planned check is unavailable, and the agent selects an alternative mechanism that obtains the same verification property, which the subsequent action then uses.",
    "parameters": [
      {
        "name": "unavailability",
        "type": "observation",
        "description": "The observation reporting that the intended tool, command, or resource is missing or failed for availability reasons."
      },
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text choosing a substitute mechanism that preserves the verification goal."
      },
      {
        "name": "action",
        "type": "action",
        "description": "The invocation that performs the check through the substitute mechanism."
      }
    ],
    "assertion_conditions": [
      "The observation establishes unavailability of a specific tool or command rather than a failure of the property being checked.",
      "The reasoning explicitly substitutes a different mechanism that targets the same property.",
      "The action implements the substitute mechanism instead of the unavailable one."
    ],
    "exclusion_conditions": [
      "The unavailable item is installed or restored and then used as originally planned.",
      "The substitute check tests a different property than the original intent.",
      "The failure reported is a genuine result about the system under test rather than a missing tool."
    ]
  },
  {
    "name": "CONFIRMS_SERVICE_EXPOSURE_VIA_NONLOCAL_PROBE",
    "definition": "The action contacts the running service through a non-loopback network address in order to confirm that it accepts connections on all interfaces, and the resulting observation shows a successful response from that address.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The request issued to the service using a non-loopback host address."
      },
      {
        "name": "result",
        "type": "observation",
        "description": "The observation containing the response received from that address."
      }
    ],
    "assertion_conditions": [
      "The address targeted by the action is not the loopback address, showing that an externally reachable interface is being exercised.",
      "The observation reports a successful response returned through that non-loopback address."
    ],
    "exclusion_conditions": [
      "The request is sent only to a loopback address, which does not establish external reachability.",
      "The probe verifies payload correctness only, without exercising a non-local interface.",
      "Configuration or source files are inspected instead of contacting the running service.",
      "The observation reports a failure to reach the service."
    ]
  },
  {
    "name": "INDEPENDENTLY_CORROBORATES_PRIOR_RESULT",
    "definition": "A later observation drawn from an independent source, such as runtime logs or process state, contains specific evidence that matches outcomes reported by earlier observations, thereby corroborating those results through a different channel.",
    "parameters": [
      {
        "name": "corroborating",
        "type": "observation",
        "description": "The later observation from an independent source such as service logs or process metadata."
      },
      {
        "name": "prior_result",
        "type": "observation",
        "description": "The earlier observation whose reported outcome is being corroborated."
      }
    ],
    "assertion_conditions": [
      "The corroborating observation comes from a different evidence source than the prior result, not a repetition of the same probe.",
      "The corroborating observation contains concrete entries, values, or identifiers that correspond to the outcome reported earlier."
    ],
    "exclusion_conditions": [
      "The two observations are merely topically similar or temporally adjacent without matching concrete values.",
      "The later observation contradicts rather than matches the earlier result.",
      "The later observation is a re-run of the same check against the same source."
    ]
  },
  {
    "name": "ASSERTS_REQUIREMENTS_VERIFIED",
    "definition": "The reasoning enumerates the task's stated requirements, ties each to concrete observed results, and concludes that every requirement is satisfied and the task is complete.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text giving the requirement-by-requirement completion assessment."
      }
    ],
    "assertion_conditions": [
      "The reasoning lists multiple distinct requirements or deliverables of the task.",
      "Each listed item is associated with a concrete observed outcome rather than an assumption or intention.",
      "The reasoning explicitly concludes that the task is complete or that all requirements are met."
    ],
    "exclusion_conditions": [
      "The reasoning describes planned future actions rather than completed verification.",
      "Some enumerated requirements are left unverified or acknowledged as unresolved.",
      "The reasoning reports individual results without concluding overall requirement satisfaction."
    ]
  }
]}

